+/** Returns a view of location-specific records for one site. */
+export function siteStore(store, site) {
+  const data = new Proxy(store.data, {
+    get(target, key) {
+      const value = target[key];
+      if (!Array.isArray(value)) return value;
+      const locations = new Set(target.locations.filter((l) => l.site === site).map((l) => l.id));
+      const batches = new Set(target.batches.filter((b) => locations.has(b.location)).map((b) => b.id));
+      const predicates = {
+        locations: (l) => locations.has(l.id),
+        batches: (b) => locations.has(b.location),
+        movements: (m) => batches.has(m.batchId),
+        stocktakes: (s) => locations.has(s.location),
+        temperatures: (r) => locations.has(r.location),
+      };
+      if (!predicates[key]) return value;
+      const visible = value.filter(predicates[key]);
+      visible.push = (...records) => value.push(...records);
+      return visible;
+    },
+  });
+  return { data, nextId: store.nextId.bind(store), save: store.save.bind(store) };
+}
